using System;
using System.Collections.Generic;
using UnityEngine;
namespace EmberBastion {
 // Small original synthesized cues. No game simulation or random state is affected.
 public sealed class BattleSound : MonoBehaviour {
  const string VolumeKey="snomet.ember-bastion.unity-comparison.sound-volume.v2";const string MuteKey="snomet.ember-bastion.unity-comparison.sound-muted.v1";
  readonly Dictionary<string,AudioClip> clips=new Dictionary<string,AudioClip>();
  readonly Dictionary<string,float> lastPlayed=new Dictionary<string,float>();
  readonly AudioSource[] voices=new AudioSource[3];readonly AudioSource[] music=new AudioSource[4];bool muted,musicPaused;int volumeLevel;int musicState=-1;
  public bool Muted {get{return muted;}}public string VolumeLabel {get{return volumeLevel==0?"소리 끔":volumeLevel==1?"소리 작게":"소리 크게";}}
  void Awake(){for(int i=0;i<voices.Length;i++){voices[i]=gameObject.AddComponent<AudioSource>();voices[i].playOnAwake=false;voices[i].spatialBlend=0;}try{volumeLevel=PlayerPrefs.HasKey(VolumeKey)?PlayerPrefs.GetInt(VolumeKey,2):(PlayerPrefs.GetInt(MuteKey,0)!=0?0:2);if(volumeLevel<0||volumeLevel>2)volumeLevel=2;}catch(Exception){volumeLevel=2;}muted=volumeLevel==0;UpdateVolume();for(int i=0;i<music.Length;i++){var track=gameObject.AddComponent<AudioSource>();track.playOnAwake=false;track.spatialBlend=0;track.loop=true;track.volume=0;track.clip=MakeMusicLayer(i);music[i]=track;}
   clips["death"]=MakeNoise("death",.11f,145,.16f);clips["coin"]=MakeCoin("coin",.12f,.09f);clips["bosscoin"]=MakeCoin("bosscoin",.22f,.16f);clips["place"]=MakeNoise("place",.10f,110,.12f);clips["upgrade"]=Make("upgrade",.19f,330,880,.13f);clips["click"]=MakeNoise("click",.045f,450,.06f);clips["invalid"]=Make("invalid",.14f,190,110,.11f);clips["attack"]=Make("attack",.07f,620,390,.10f);clips["blast"]=Make("blast",.16f,160,65,.16f);
   clips["sword"]=MakeNoise("sword",.08f,1100,.12f);clips["bow"]=Make("bow",.08f,820,270,.12f);clips["bombshot"]=MakeNoise("bombshot",.09f,100,.12f);clips["frostshot"]=Make("frostshot",.10f,1250,1700,.12f);
   clips["ember"]=Make("ember",.20f,380,110,.18f);clips["warn"]=Make("warn",.19f,530,670,.14f);
   clips["danger"]=Make("danger",.24f,700,360,.16f);clips["roar"]=Make("roar",.23f,165,95,.15f);clips["wave"]=Make("wave",.18f,440,660,.12f);
   clips["win"]=Make("win",.32f,470,790,.14f);clips["lose"]=Make("lose",.32f,330,140,.14f);
   if(Smoke()){foreach(string name in new[]{"sword","bow","bombshot","frostshot"}){var data=new float[clips[name].samples];if(!clips[name].GetData(data,0))throw new InvalidOperationException("Cannot read "+name);float max=0;foreach(float value in data)max=Mathf.Max(max,Mathf.Abs(value));if(max<.01f||max>.15f)throw new InvalidOperationException("Invalid "+name+" samples");Debug.Log("SOUND_SAMPLE "+name+" "+max);}if(Application.absoluteURL.Contains("fx-smoke=soundclasses"))StartCoroutine(TestClassSounds());var sample=new float[clips["attack"].samples];if(!clips["attack"].GetData(sample,0))throw new InvalidOperationException("Cannot read sound samples");float peak=0;foreach(float v in sample)peak=Mathf.Max(peak,Mathf.Abs(v));if(peak<.01f||peak>.3f)throw new InvalidOperationException("Invalid sound samples");Debug.Log("SOUND_READY muted="+muted+" peak="+peak);}
  }
  System.Collections.IEnumerator TestClassSounds(){yield return new WaitForSecondsRealtime(1.5f);foreach(string name in new[]{"sword","bow","bombshot","frostshot"}){yield return new WaitForSecondsRealtime(.2f);Play(name);}}
  static AudioClip Make(string name,float seconds,float start,float end,float gain){const int rate=22050;int length=Mathf.CeilToInt(rate*seconds);var samples=new float[length];double phase=0;for(int i=0;i<length;i++){float t=(float)i/Mathf.Max(1,length-1);float frequency=Mathf.Lerp(start,end,t);phase+=2*Math.PI*frequency/rate;float envelope=Mathf.Min(1,t*30)*Mathf.Pow(1-t,1.8f);samples[i]=(float)(Math.Sin(phase)*.8+Math.Sin(phase*2)*.2)*gain*envelope;}var clip=AudioClip.Create("ember-"+name,length,1,rate,false);clip.SetData(samples,0);return clip;}
  static AudioClip MakeCoin(string name,float seconds,float gain){const int rate=22050;int length=Mathf.CeilToInt(rate*seconds);var samples=new float[length];double phase=0;for(int i=0;i<length;i++){float t=(float)i/Mathf.Max(1,length-1);float frequency=t<.5f?760:1140;phase+=2*Math.PI*frequency/rate;float local=t<.5f?t*2:(t-.5f)*2;float envelope=Mathf.Min(1,local*20)*Mathf.Pow(1-local,1.5f);samples[i]=(float)(Math.Sin(phase)*.75+Math.Sin(phase*2)*.25)*gain*envelope;}var clip=AudioClip.Create("ember-"+name,length,1,rate,false);clip.SetData(samples,0);return clip;}
  static AudioClip MakeNoise(string name,float seconds,float frequency,float gain){const int rate=22050;int length=Mathf.CeilToInt(rate*seconds);var samples=new float[length];uint random=1234567;double phase=0;for(int i=0;i<length;i++){float t=(float)i/Mathf.Max(1,length-1);random=1664525*random+1013904223;float noise=((random>>8)/(float)0xFFFFFF)*2-1;phase+=2*Math.PI*frequency/rate;float envelope=Mathf.Min(1,t*40)*Mathf.Pow(1-t,2);samples[i]=(float)(Math.Sin(phase)*.7+noise*.3)*gain*envelope;}var clip=AudioClip.Create("ember-"+name,length,1,rate,false);clip.SetData(samples,0);return clip;}
  // Four equal-length loops are synthesized independently of the combat RNG.
  static AudioClip MakeMusicLayer(int layer){const int rate=11025,length=rate*8;var data=new float[length];for(int i=0;i<length;i++){double t=(double)i/rate;double beat=t-Math.Floor(t);double half=t*2-Math.Floor(t*2);double sample=0;if(layer==0){int note=(int)(t/2)%4;double frequency=new[]{110.0,130.81,146.83,123.47}[note];sample=(Math.Sin(2*Math.PI*frequency*t)+.35*Math.Sin(2*Math.PI*frequency*1.5*t))*.035*Math.Pow(Math.Sin(Math.PI*(t%2)/2),2);}else if(layer==1){sample=Math.Sin(2*Math.PI*(85*beat-20*beat*beat))*.12*Math.Exp(-beat*14);}else if(layer==2){sample=(Math.Sin(2*Math.PI*220*t)+Math.Sin(2*Math.PI*277.18*t))*.018*Math.Pow(Math.Sin(Math.PI*(t%2)/2),2);}else{sample=Math.Sin(2*Math.PI*(170*half-35*half*half))*.045*Math.Exp(-half*23);}data[i]=(float)sample;}var clip=AudioClip.Create("ember-music-"+layer,length,1,rate,false);clip.SetData(data,0);return clip;}
  public void MusicState(bool fighting,bool paused,int enemies,bool decided){if(muted||!Application.isFocused){if(!musicPaused){foreach(var track in music)if(track!=null&&track.isPlaying)track.Pause();musicPaused=true;}return;}if(musicPaused){foreach(var track in music)if(track!=null)track.UnPause();musicPaused=false;}bool any=false;foreach(var track in music)if(track!=null&&track.isPlaying)any=true;if(!any){foreach(var track in music){track.timeSamples=0;track.Play();}}int state=!fighting?0:decided?4:enemies>=80?3:enemies>=50?2:1;float master=volumeLevel==1?.5f:1f;for(int i=0;i<music.Length;i++){bool on=i==0||i==1&&state>=1&&state<=3||i==2&&state==2||i==3&&state==3;float target=on?master*(paused?.15f:1f):0;music[i].volume=Mathf.MoveTowards(music[i].volume,target,Time.unscaledDeltaTime*1.5f);}if(state!=musicState){musicState=state;if(Smoke())Debug.Log("MUSIC_STATE "+state);}}
  static bool Smoke(){return Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&(Application.absoluteURL.Contains("fx-smoke=sound")||Application.absoluteURL.Contains("fx-smoke=dangersound"));}
  void UpdateVolume(){foreach(var voice in voices)if(voice!=null){voice.volume=volumeLevel==1?.4f:.8f;if(muted)voice.Stop();}}
  void OnApplicationFocus(bool focused){if(!focused){foreach(var voice in voices)if(voice!=null)voice.Stop();foreach(var track in music)if(track!=null&&track.isPlaying)track.Pause();musicPaused=true;}}
  public void Toggle(){volumeLevel=(volumeLevel+1)%3;muted=volumeLevel==0;UpdateVolume();if(muted){foreach(var track in music)if(track!=null&&track.isPlaying)track.Pause();musicPaused=true;}try{PlayerPrefs.SetInt(VolumeKey,volumeLevel);PlayerPrefs.SetInt(MuteKey,muted?1:0);PlayerPrefs.Save();}catch(Exception){}if(Smoke())Debug.Log("SOUND_TOGGLE muted="+muted+" level="+volumeLevel);}

  public void Play(string kind){if(muted||!Application.isFocused)return;AudioClip clip;if(!clips.TryGetValue(kind,out clip)||clip==null)return;bool attack=kind=="attack"||kind=="sword"||kind=="bow"||kind=="bombshot"||kind=="frostshot";string cooldownKey=attack?"attack":kind;float cooldown=kind=="click"?.05f:kind=="invalid"?.15f:attack?.12f:kind=="blast"?.18f:kind=="coin"?.12f:kind=="death"?.08f:.3f,last;if(lastPlayed.TryGetValue(cooldownKey,out last)&&Time.unscaledTime-last<cooldown)return;AudioSource available=null;foreach(var voice in voices)if(voice!=null&&!voice.isPlaying){available=voice;break;}if(available==null){if(kind!="win"&&kind!="lose"&&kind!="danger")return;available=voices[0];available.Stop();}lastPlayed[cooldownKey]=Time.unscaledTime;available.PlayOneShot(clip);if(Smoke())Debug.Log("SOUND_PLAY "+kind);}
  void OnDestroy(){foreach(var track in music)if(track!=null&&track.clip!=null)Destroy(track.clip);foreach(var clip in clips.Values)if(clip!=null)Destroy(clip);}
 }
}
